//! File Generated by Claude Opus 5.5
//! Analysis for a person playing: simulates the rest of the game after each
//! move the way one of the Monte Carlo bots does, to show which moves it
//! rates best, the person's chance of finishing in each place and everyone's
//! average final score.
use std::cmp::Reverse;
use crate::core::{ GameState, Ruleset, Turn };
use crate::evaluators::{ greedy, claude_heuristic::{ claude, claude_values }, mce_heuristic::opponent };
use crate::simulation::simulated_deal;

/// Bots that can analyse, the first by default
pub const ANALYSTS: &[&str] = &["mce heuristic", "mce race", "mce score"];
/// Moves listed, best first
pub const TOP: usize = 5;
/// Games simulated in each round of narrowing the moves down to the best few
const ROUND_GAMES: u32 = 1000;
/// Games simulated for each move shown
const GAMES: u32 = 300;
/// Moves mce heuristic keeps after ranking them with the claude heuristic
const HEURISTIC_MCE_MOVES: usize = 16;
/// Points of margin over the best opponent that mce heuristic values as much as
/// beating one
const MARGIN_PER_WIN: f64 = 60.0;

type Policy<const N: usize, const S: usize, R> = fn(&GameState<N, S, R>, &[Turn]) -> usize;

/// What a bot maximises in a simulated game
#[derive(Clone, Copy)]
enum Goal {
    /// Opponents beaten plus a share of the margin over the best, like mce heuristic
    PlaceAndMargin,
    /// Opponents beaten, like mce race
    Place,
    /// Its own score, like mce score
    Score,
}

/// How a bot simulates games
struct Analyst<const N: usize, const S: usize, R: Ruleset> {
    /// Only the moves the claude heuristic rates best are considered
    prune: bool,
    /// Plays the analysed player's moves
    own: Policy<N, S, R>,
    /// Plays the opponents' moves
    others: Policy<N, S, R>,
    goal: Goal,
}

fn analyst<const N: usize, const S: usize, R: Ruleset>(name: &str) -> Analyst<N, S, R> {
    match name {
        "mce heuristic" => Analyst { prune: true, own: claude, others: opponent, goal: Goal::PlaceAndMargin },
        "mce score" => Analyst { prune: false, own: greedy, others: greedy, goal: Goal::Score },
        _ => Analyst { prune: false, own: greedy, others: greedy, goal: Goal::Place },
    }
}

/// Results of the games simulated after a move
#[derive(Clone, Copy, Default)]
pub struct Stats {
    games: u32,
    /// Times the analysed player finished in each place, ties shared out
    places: [f32; 4],
    /// Sum of each player's final score
    scores: [u32; 4],
    /// Sum of what the analyst maximises
    value: f64,
}

impl Stats {
    /// Chance of the analysed player finishing in place `k`, 0 for first
    pub fn place(&self, k: usize) -> f32 {
        self.places[k] / self.games as f32
    }

    /// Average final score of player `p`
    pub fn score(&self, p: usize) -> f32 {
        self.scores[p] as f32 / self.games as f32
    }

    fn value(&self) -> f64 {
        self.value / self.games as f64
    }
}

/// Adds `games` games simulated after `turn` to `stats`
fn simulate<const N: usize, const S: usize, R: Ruleset>(
    state: &GameState<N, S, R>,
    turn: Turn,
    analyst: &Analyst<N, S, R>,
    games: u32,
    stats: &mut Stats,
) {
    let me = state.player_order[0] as usize;
    let mut start = *state;
    start.play_turn(turn);
    let policies: [Policy<N, S, R>; N] =
        std::array::from_fn(|p| if p == me { analyst.own } else { analyst.others });
    for _ in 0..games {
        let mut s = start;
        s.play_out(simulated_deal, policies);
        let scores: [u32; N] = std::array::from_fn(|p| s.score(p));
        let mine = scores[me];
        let above = scores.iter().filter(|&&x| x > mine).count();
        let level = scores.iter().filter(|&&x| x == mine).count();
        for place in above..above + level {
            stats.places[place] += 1.0 / level as f32;
        }
        for p in 0..N {
            stats.scores[p] += scores[p];
        }
        // Opponents below count one each, opponents level a half
        let beaten = (N - above - level) as f64 + (level - 1) as f64 / 2.0;
        let best = (0..N).filter(|&p| p != me).map(|p| scores[p]).max().unwrap();
        stats.value += match analyst.goal {
            Goal::PlaceAndMargin => beaten + (mine as f64 - best as f64) / MARGIN_PER_WIN,
            Goal::Place => beaten,
            Goal::Score => mine as f64,
        };
        stats.games += 1;
    }
}

/// The moves the analyst rates best, best first. Moves are narrowed down in
/// rounds that share the same number of games between the moves left, keeping
/// the better half each time. The moves left are then simulated afresh, so
/// their results aren't flattered by having come through the narrowing.
pub fn top_moves<const N: usize, const S: usize, R: Ruleset>(
    state: &GameState<N, S, R>,
    turns: &[Turn],
    name: &str,
) -> Vec<(usize, Stats)> {
    let analyst = analyst::<N, S, R>(name);
    let mut moves: Vec<(usize, Stats)> = if analyst.prune {
        let mut ranked: Vec<(usize, i32)> = claude_values(state, turns).enumerate().collect();
        ranked.sort_unstable_by_key(|&(_, v)| Reverse(v));
        ranked.truncate(HEURISTIC_MCE_MOVES);
        ranked.into_iter().map(|(i, _)| (i, Stats::default())).collect()
    } else {
        (0..turns.len()).map(|i| (i, Stats::default())).collect()
    };
    while moves.len() > TOP {
        let games = (ROUND_GAMES / moves.len() as u32).max(8);
        for (i, stats) in moves.iter_mut() {
            simulate(state, turns[*i], &analyst, games, stats);
        }
        moves.sort_by(|a, b| b.1.value().total_cmp(&a.1.value()));
        moves.truncate((moves.len() / 2).max(TOP));
    }
    for (i, stats) in moves.iter_mut() {
        *stats = Stats::default();
        simulate(state, turns[*i], &analyst, GAMES, stats);
    }
    moves.sort_by(|a, b| b.1.value().total_cmp(&a.1.value()));
    moves
}

/// Results of one move as the analyst simulates it
pub fn evaluate<const N: usize, const S: usize, R: Ruleset>(
    state: &GameState<N, S, R>,
    turns: &[Turn],
    i: usize,
    name: &str,
) -> Stats {
    let mut stats = Stats::default();
    simulate(state, turns[i], &analyst::<N, S, R>(name), GAMES, &mut stats);
    stats
}
